pid_t target_pid = 1001;
pid_t sid;

// Syntax: pid_t getsid(pid_t pid);

// Get own Session ID (using pid=0)
sid = getsid(0);

// Get Session ID of target_pid
sid = getsid(target_pid);

if (sid == (pid_t)-1) {
    // Failure check
    if (errno == ESRCH) {
        /* No process found with target_pid */
    } else if (errno == EPERM) {
        /* Session Isolation/Permission restriction */
    }
} else {
    /* Success: sid contains the session ID */
}

// Related: getsid(getpid()), getsid(0)
// Related System Calls: setsid()
